#!/usr/bin/env python3
import json


class Component:
    def __init__(self, name, comp_type):
        self.name = name
        self.type = comp_type

    def to_dict(self):
        return {"name": self.name, "type": self.type}


class Feature:
    def __init__(self, name, description):
        self.name = name
        self.description = description

    def to_dict(self):
        return {"name": self.name, "description": self.description}


class Requirement:
    def __init__(self, frontend, backend, language, complexity):
        self.frontend = frontend
        self.backend = backend
        self.language = language
        self.complexity = complexity

    def to_dict(self):
        return {
            "frontend": self.frontend,
            "backend": self.backend,
            "language": self.language,
            "complexity": self.complexity,
        }


class IntentSpec:
    def __init__(self, name, description, components, features, requirements):
        self.name = name
        self.description = description
        self.components = components
        self.components_count = len(components)
        self.features = features
        self.features_count = len(features)
        self.requirements = requirements
        self.confidence = 85

    def to_dict(self):
        return {
            "name": self.name,
            "description": self.description,
            "components": [c.to_dict() for c in self.components],
            "components_count": self.components_count,
            "features": [f.to_dict() for f in self.features],
            "features_count": self.features_count,
            "requirements": self.requirements.to_dict(),
            "confidence": self.confidence,
        }

    def to_json(self):
        return json.dumps(self.to_dict(), indent=2, ensure_ascii=False)


def extract_app_name(user_input):
    """자연어 입력에서 앱 이름 추출"""
    if not user_input:
        return "unknown_app"

    # TODO/투두가 우선순위 높음
    if "TODO" in user_input or "투두" in user_input:
        return "todo_app"
    # ML이 우선순위 높음
    if "ML" in user_input or "머신러닝" in user_input:
        return "ml_pipeline"
    # 웹 서버 매칭
    if "웹" in user_input and "서버" in user_input:
        return "web_server"
    if "웹" in user_input:
        return "web_server"
    if "파이프라인" in user_input:
        return "ml_pipeline"

    return "default_app"


def detect_components(user_input):
    """입력에서 컴포넌트 자동 감지"""
    if "TODO" in user_input or "투두" in user_input:
        return [
            Component("TodoList", "view"),
            Component("AddTodo", "form"),
            Component("DeleteTodo", "action"),
        ]
    elif "웹" in user_input and "서버" in user_input:
        return [
            Component("Router", "view"),
            Component("Handler", "action"),
            Component("Response", "model"),
        ]
    else:
        return [
            Component("Main", "view"),
            Component("Handler", "form"),
        ]


def detect_features(user_input):
    """입력에서 기능 자동 감지"""
    if "TODO" in user_input or "투두" in user_input:
        return [
            Feature("CRUD", "Create, Read, Update, Delete"),
            Feature("persistence", "데이터 저장"),
            Feature("filtering", "상태 필터링"),
        ]
    else:
        return [
            Feature("basic", "기본 기능"),
        ]


def detect_requirements(user_input):
    """입력에서 기술 요구사항 자동 감지"""
    frontend = "web"
    backend = "in-memory"
    language = "fv-lang"
    complexity = "simple"

    if "웹" in user_input:
        frontend = "web"
        complexity = "medium"
    if "ML" in user_input or "머신러닝" in user_input:
        backend = "database"
        complexity = "complex"

    return Requirement(frontend, backend, language, complexity)


def parse_intent(user_input):
    """사용자 입력을 IntentSpec로 변환"""
    name = extract_app_name(user_input)
    components = detect_components(user_input)
    features = detect_features(user_input)
    requirements = detect_requirements(user_input)

    return IntentSpec(name, user_input, components, features, requirements)


def main():
    print("=== Phase 0 Day 1: Intent Parser ===\n")

    # Test 1: "간단한 TODO 앱"
    input1 = "간단한 TODO 앱 만들어줘"
    spec1 = parse_intent(input1)
    json1 = spec1.to_json()

    print("=== Test 1: TODO 앱 ===")
    print(json1)
    print()

    # Test 2: "웹 서버"
    input2 = "웹 서버 만들어줘"
    spec2 = parse_intent(input2)
    json2 = spec2.to_json()

    print("=== Test 2: 웹 서버 ===")
    print(json2)
    print()

    # Test 3: "ML 파이프라인"
    input3 = "ML 파이프라인 만들어줘"
    spec3 = parse_intent(input3)
    json3 = spec3.to_json()

    print("=== Test 3: ML 파이프라인 ===")
    print(json3)
    print()

    # Validation
    passed = 0
    total = 3

    # Validate Test 1
    if (
        spec1.name == "todo_app"
        and spec1.components_count == 3
        and spec1.features_count == 3
        and spec1.confidence == 85
    ):
        passed += 1
        print("✅ Test 1 PASSED")
    else:
        print("❌ Test 1 FAILED")
        print(
            f"  Expected: name=todo_app, components=3, features=3, confidence=85"
        )
        print(
            f"  Got: name={spec1.name}, components={spec1.components_count}, features={spec1.features_count}, confidence={spec1.confidence}"
        )

    # Validate Test 2
    if (
        spec2.name == "web_server"
        and spec2.components_count == 3
        and spec2.requirements.frontend == "web"
        and spec2.requirements.complexity == "medium"
    ):
        passed += 1
        print("✅ Test 2 PASSED")
    else:
        print("❌ Test 2 FAILED")
        print(
            f"  Expected: name=web_server, components=3, frontend=web, complexity=medium"
        )
        print(
            f"  Got: name={spec2.name}, components={spec2.components_count}, frontend={spec2.requirements.frontend}, complexity={spec2.requirements.complexity}"
        )

    # Validate Test 3
    if (
        spec3.name == "ml_pipeline"
        and spec3.requirements.complexity == "complex"
        and spec3.requirements.backend == "database"
    ):
        passed += 1
        print("✅ Test 3 PASSED")
    else:
        print("❌ Test 3 FAILED")
        print(
            f"  Expected: name=ml_pipeline, complexity=complex, backend=database"
        )
        print(
            f"  Got: name={spec3.name}, complexity={spec3.requirements.complexity}, backend={spec3.requirements.backend}"
        )

    print(f"\n✅ {passed}/{total} 테스트 완료!")

    accuracy = (passed / total) * 100
    if accuracy >= 90:
        print("✨ Intent 정확도: 90%+ (SUCCESS!)")
        return 0
    else:
        print(f"⚠️ Intent 정확도: {accuracy:.0f}%")
        return 1


if __name__ == "__main__":
    exit(main())

