        attr_counts: Dict[str, int] = {}
        for memory in self.memory_buffer:
            for attr in memory["knowledge"]["attributes"]:
                key = f"{attr['name']}:{attr['value']}"
                attr_counts[key] = attr_counts.get(key, 0) + 1

        # 70% 이상 반복된 속성만 보존
        threshold = len(self.memory_buffer) * 0.7
        consolidated["common_attributes"] = {
