class CodeAttribute:
    """코드 속성 (의도, 제약, 목표)"""
    name: str
    value: str
    confidence: float  # 0~1
    source: str  # "user_input", "code_analysis", "test_feedback"

    def to_dict(self):
        return {
            "name": self.name,
            "value": self.value,
            "confidence": self.confidence,
            "source": self.source,
        }


@dataclass
class DesignPrinciple:
    """설계 원칙"""
    principle: str
    rationale: str
    priority: float  # 0~1 (높을수록 중요)

    def to_dict(self):
        return {
            "principle": self.principle,
            "rationale": self.rationale,
            "priority": self.priority,
        }


class WorldModel:
    """앱의 '세계'를 모델링"""

    def __init__(self, app_name: str):
        self.app_name = app_name
        self.attributes: List[CodeAttribute] = []
        self.principles: List[DesignPrinciple] = []
        self.learned_patterns: Dict[str, List[str]] = {}
        self.constraints: List[str] = []
        self.goals: List[str] = []

    def add_attribute(self, name: str, value: str, confidence: float, source: str):
        """속성 추가 (의도, 목표, 제약)"""
        attr = CodeAttribute(name, value, confidence, source)
        self.attributes.append(attr)

