        """설계 원칙 추가"""
        p = DesignPrinciple(principle, rationale, priority)
        self.principles.append(p)

    def add_constraint(self, constraint: str):
        """제약조건 추가"""
        self.constraints.append(constraint)

    def add_goal(self, goal: str):
        """목표 추가"""
        self.goals.append(goal)

    def learn_from_code(self, code: str):
        """코드 분석으로부터 학습"""
        # 구조체 개수
        struct_count = code.count("struct ")
        if struct_count > 0:
            self.add_attribute(
                "struct_count",
                str(struct_count),
                0.9,
                "code_analysis"
            )

        # 함수 개수
        fn_count = code.count("fn ")
        if fn_count > 0:
            self.add_attribute(
                "function_count",
                str(fn_count),
                0.9,
                "code_analysis"
            )

        # 에러 처리 존재
        if "Result<" in code:
            self.add_attribute(
                "error_handling",
                "explicit",
                0.85,
                "code_analysis"
            )

        # 타입 힌트
        if "->" in code:
            self.add_attribute(
                "type_safety",
                "high",
                0.9,
                "code_analysis"
            )

