        """다음 개선 영역 예측"""
        improvements = []

        # 구조체가 적으면 더 추가
        struct_attr = self._get_attribute("struct_count")
        if struct_attr and int(struct_attr.value) < 3:
            improvements.append({
                "area": "type_definition",
                "suggestion": "Add more struct definitions for better typing",
                "priority": 0.8,
            })

        # 함수가 적으면 더 추가
