            improvements.append({
                "area": "type_safety",
                "suggestion": "Add type hints to all functions",
                "priority": 0.85,
            })

        return improvements

    def _get_attribute(self, name: str) -> Any:
        """속성 검색"""
        for attr in self.attributes:
            if attr.name == name:
                return attr
        return None

    def get_design_guidelines(self) -> str:
        """설계 가이드라인 생성"""
        lines = []
        lines.append(f"Design Guidelines for {self.app_name}:")
        lines.append("")

        if self.goals:
            lines.append("Goals:")
            for goal in self.goals:
                lines.append(f"  - {goal}")
            lines.append("")

        if self.constraints:
            lines.append("Constraints:")
            for constraint in self.constraints:
                lines.append(f"  - {constraint}")
            lines.append("")

        if self.principles:
            lines.append("Design Principles:")
            sorted_principles = sorted(self.principles, key=lambda p: p.priority, reverse=True)
            for p in sorted_principles[:3]:  # 상위 3개만
                lines.append(f"  - {p.principle} ({p.priority:.0%})")
            lines.append("")

        if self.attributes:
            lines.append("Current State:")
            high_conf = [a for a in self.attributes if a.confidence >= 0.85]
            for attr in high_conf[:5]:  # 상위 5개
                lines.append(f"  - {attr.name}: {attr.value} ({attr.confidence:.0%})")

        return "\n".join(lines)

    def to_dict(self):
        return {
            "app_name": self.app_name,
            "attributes": [a.to_dict() for a in self.attributes],
            "principles": [p.to_dict() for p in self.principles],
            "constraints": self.constraints,
            "goals": self.goals,
            "next_improvements": self.predict_next_improvement(),
        }

    def to_json(self):
        return json.dumps(self.to_dict(), indent=2, ensure_ascii=False)


class CatastrophicForgettingPrevention:
